import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

type Row = Record<string, unknown>;

const LEDGER_TYPES = ['예산일계표', '월계표', '수입·지출부', '자금출납장', '은행이체명세서', '지출원인행위부', '수입징수부', '세출·세입총괄표'];
const CASH_SCOPES = ['전체', '금융기관별', '프로젝트별', '결의 담당자별'];
const VIEW_FORMS = ['상세', '총괄'];
// 가정: 권한 범위를 판정하는 메뉴 이름
const MENU_NAME = '예산장부 조회';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

const JOURNAL_FROM =
  ' FROM journal_entry je'
  + ' JOIN journal_entry_line l ON l.journal_entry_id = je.journal_entry_id'
  + ' JOIN expense_resolution r ON r.expense_resolution_id = je.expense_resolution_id'
  + ' LEFT JOIN approval_document d ON d.approval_document_id = r.approval_document_id'
  + ' LEFT JOIN budget_account ba ON ba.budget_account_id = l.budget_account_id'
  + ' WHERE je.entry_date BETWEEN CAST(:fromDate AS date) AND CAST(:toDate AS date)';

// 가정: 결의서에는 일자 컬럼이 없어 생성 일자를 기준일로 본다
const RESOLUTION_FROM =
  ' FROM expense_resolution r'
  + ' LEFT JOIN approval_document d ON d.approval_document_id = r.approval_document_id'
  + ' WHERE CAST(r.created_at AS date) BETWEEN CAST(:fromDate AS date) AND CAST(:toDate AS date)';

function text(v: unknown): string {
  return typeof v === 'string' ? v.trim() : '';
}

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function idOf(v: unknown, label: string): string {
  const s = text(v);
  if (!/^\d+$/.test(s)) {
    throw invalid(label + ' 형식이 올바르지 않습니다.');
  }
  return s;
}

function journalInner(type: string, form: string, extra: string): string {
  const detail =
    'SELECT je.entry_date AS entry_date, COALESCE(l.summary, je.summary) AS summary,'
    + ' l.debit_amount AS debit_amount, l.credit_amount AS credit_amount,'
    + ' r.resolution_amount AS resolution_amount, l.debit_amount AS amount'
    + JOURNAL_FROM + extra;
  const sum = ' COALESCE(SUM(l.debit_amount), 0) AS debit_amount, COALESCE(SUM(l.credit_amount), 0) AS credit_amount,'
    + ' CAST(0 AS numeric) AS resolution_amount, COALESCE(SUM(l.debit_amount), 0) AS amount';
  if (type === '예산일계표') {
    return 'SELECT je.entry_date AS entry_date, CAST(NULL AS varchar) AS summary,' + sum
      + JOURNAL_FROM + extra + ' GROUP BY je.entry_date';
  }
  if (type === '월계표') {
    return 'SELECT CAST(date_trunc(\'month\', je.entry_date) AS date) AS entry_date, CAST(NULL AS varchar) AS summary,' + sum
      + JOURNAL_FROM + extra + ' GROUP BY CAST(date_trunc(\'month\', je.entry_date) AS date)';
  }
  if (type === '세출·세입총괄표') {
    return 'SELECT CAST(NULL AS date) AS entry_date, COALESCE(ba.name, \'예산과목 없음\') AS summary,' + sum
      + JOURNAL_FROM + extra + ' GROUP BY COALESCE(ba.name, \'예산과목 없음\')';
  }
  if (type === '수입·지출부') {
    return detail + ' AND l.budget_account_id IS NOT NULL';
  }
  if (type === '수입징수부') {
    const income = JOURNAL_FROM + extra + ' AND ba.income_expense_type = \'수입\'';
    if (form === '총괄') {
      return 'SELECT CAST(NULL AS date) AS entry_date, CAST(\'합계\' AS varchar) AS summary,' + sum + income;
    }
    return detail + ' AND ba.income_expense_type = \'수입\'';
  }
  return detail;
}

function resolutionInner(type: string, form: string, extra: string): string {
  // 가정: 은행이체명세서는 통장거래내역 방식의 결의서를 대상으로 한다
  const method = type === '은행이체명세서' ? ' AND r.resolution_method = \'통장거래내역\'' : '';
  if (form === '총괄') {
    return 'SELECT CAST(NULL AS date) AS entry_date, CAST(\'합계\' AS varchar) AS summary,'
      + ' CAST(0 AS numeric) AS debit_amount, CAST(0 AS numeric) AS credit_amount,'
      + ' COALESCE(SUM(r.resolution_amount), 0) AS resolution_amount, COALESCE(SUM(r.resolution_amount), 0) AS amount'
      + RESOLUTION_FROM + extra + method;
  }
  return 'SELECT CAST(r.created_at AS date) AS entry_date, CAST(r.resolution_method AS varchar) AS summary,'
    + ' CAST(0 AS numeric) AS debit_amount, CAST(0 AS numeric) AS credit_amount,'
    + ' r.resolution_amount AS resolution_amount, r.resolution_amount AS amount'
    + RESOLUTION_FROM + extra + method;
}

