import { useState } from 'react';
import { Band, DataTable, DateInput, DateText, ErrorText, Field, Filters, LookupSelect, Num, Pager, Select, Tiles, call, useData } from '../kit';
import type { Column, Page, PageProps, Row } from '../kit';

const LEDGER_TYPES = ['예산일계표', '월계표', '수입·지출부', '자금출납장', '은행이체명세서', '지출원인행위부', '수입징수부', '세출·세입총괄표'];
const CASH_SCOPES = ['전체', '금융기관별', '프로젝트별', '결의 담당자별'];
const VIEW_FORMS = ['상세', '총괄'];
const FORM_TYPES = ['은행이체명세서', '지출원인행위부', '수입징수부'];
const SIZE = 20;

interface Cond {
  ledgerType: string;
  fromDate: string;
  toDate: string;
  cashBookScope: string;
  partnerId: number | string;
  projectId: number | string;
  resolverId: number | string;
  viewForm: string;
}

const EMPTY: Cond = {
  ledgerType: '',
  fromDate: '',
  toDate: '',
  cashBookScope: '전체',
  partnerId: '',
  projectId: '',
  resolverId: '',
  viewForm: '상세',
};

export default function FnSfr00501Page({ role }: PageProps) {
  const [form, setForm] = useState<Cond>(EMPTY);
  const [query, setQuery] = useState<Cond | null>(null);
  const [pageNo, setPageNo] = useState(0);
  const [message, setMessage] = useState('');

  const { data, error, loading } = useData<Page>(async () => {
    if (!query) {
      return { items: [], page: 0, size: SIZE, total: 0 };
    }
    const q: Row = {
      ledgerType: query.ledgerType,
      fromDate: query.fromDate,
      toDate: query.toDate,
      page: pageNo,
      size: SIZE,
    };
    if (query.ledgerType === '자금출납장') {
      q.cashBookScope = query.cashBookScope;
      if (query.cashBookScope === '금융기관별') {
        q.partnerId = query.partnerId;
      }
      if (query.cashBookScope === '프로젝트별') {
        q.projectId = query.projectId;
      }
      if (query.cashBookScope === '결의 담당자별') {
        q.resolverId = query.resolverId;
      }
    }
    if (FORM_TYPES.includes(query.ledgerType)) {
      q.viewForm = query.viewForm;
    }
    return call<Page>('GET', '/budget-ledgers', role, undefined, q);
  }, [query, pageNo]);

  const set = (patch: Partial<Cond>) => setForm({ ...form, ...patch });

  const search = () => {
    if (!form.ledgerType) {
      setMessage('장부 종류를 선택해 주세요.');
      return;
    }
    if (!form.fromDate || !form.toDate) {
      setMessage('조회 시작일과 종료일을 입력해 주세요.');
      return;
    }
    if (form.fromDate > form.toDate) {
      setMessage('조회 시작일은 종료일보다 늦을 수 없습니다.');
      return;
    }
    if (form.ledgerType === '자금출납장') {
      if (form.cashBookScope === '금융기관별' && form.partnerId === '') {
        setMessage('금융거래처를 선택해 주세요.');
        return;
      }
      if (form.cashBookScope === '프로젝트별' && form.projectId === '') {
        setMessage('프로젝트를 선택해 주세요.');
        return;
      }
      if (form.cashBookScope === '결의 담당자별' && form.resolverId === '') {
        setMessage('결의 담당자를 선택해 주세요.');
        return;
      }
    }
    setMessage('');
    setPageNo(0);
    setQuery({ ...form });
  };

  const reset = () => {
    setForm(EMPTY);
    setQuery(null);
    setPageNo(0);
    setMessage('');
  };

  const columns: Column[] = [
    { key: 'entryDate', label: '전표 일자', render: (row) => <DateText value={row.entryDate} /> },
    { key: 'summary', label: '적요' },
    { key: 'debitAmount', label: '차변 금액', render: (row) => <Num value={row.debitAmount} /> },
    { key: 'creditAmount', label: '대변 금액', render: (row) => <Num value={row.creditAmount} /> },
    { key: 'resolutionAmount', label: '결의 금액', render: (row) => <Num value={row.resolutionAmount} /> },
  ];

  const items = data ? data.items : [];
  const totalAmount = items.length > 0 ? items[0].totalAmount : 0;

  return (
    <div>
      <h1>예산장부 조회</h1>
      <Filters onSearch={search} onReset={reset}>
        <Field label='장부 종류' required>
          <Select
            value={form.ledgerType}
            onChange={(v) => set({ ledgerType: v })}
            options={LEDGER_TYPES.map((t): [string, string] => [t, t])}
          />
        </Field>
        <Field label='조회 시작일' required>
          <DateInput value={form.fromDate} onChange={(v) => set({ fromDate: v })} />
        </Field>
        <Field label='조회 종료일' required>
          <DateInput value={form.toDate} onChange={(v) => set({ toDate: v })} />
        </Field>
        {form.ledgerType === '자금출납장' && (
          <Field label='자금출납장 조회 구분'>
            <Select
              value={form.cashBookScope}
              onChange={(v) => set({ cashBookScope: v })}
              options={CASH_SCOPES.map((t): [string, string] => [t, t])}
            />
          </Field>
        )}
        {form.ledgerType === '자금출납장' && form.cashBookScope === '금융기관별' && (
          <Field label='금융기관별 조회 대상 금융거래처' required>
            <LookupSelect table='partner' role={role} value={form.partnerId} onChange={(v) => set({ partnerId: v })} />
          </Field>
        )}
        {form.ledgerType === '자금출납장' && form.cashBookScope === '프로젝트별' && (
          <Field label='프로젝트별 조회 대상' required>
            <LookupSelect table='project' role={role} value={form.projectId} onChange={(v) => set({ projectId: v })} />
          </Field>
        )}
        {form.ledgerType === '자금출납장' && form.cashBookScope === '결의 담당자별' && (
          <Field label='결의 담당자별 조회 대상 담당자' required>
            <LookupSelect table='employee' role={role} value={form.resolverId} onChange={(v) => set({ resolverId: v })} />
          </Field>
        )}
        {FORM_TYPES.includes(form.ledgerType) && (
          <Field label='조회 형태'>
            <Select
              value={form.viewForm}
              onChange={(v) => set({ viewForm: v })}
              options={VIEW_FORMS.map((t): [string, string] => [t, t])}
            />
          </Field>
        )}
      </Filters>
      {message && <ErrorText text={message} />}
      {error && <ErrorText text={error} />}
      {!query && <p>장부 종류와 조회 기간을 입력한 뒤 조회해 주세요.</p>}
      {query && (
        <div>
          <Tiles items={[['조회 건수', <Num value={data ? data.total : 0} />], ['합계 금액', <Num value={totalAmount} />]]} />
          <Band total={data ? data.total : 0} />
          <DataTable
            columns={columns}
            rows={items}
            empty={loading ? '불러오는 중입니다.' : '조회 조건에 해당하는 내역이 없습니다. 조회 조건을 바꿔 다시 조회해 주세요.'}
          />
          <Pager page={pageNo} size={SIZE} total={data ? data.total : 0} onPage={setPageNo} />
        </div>
      )}
    </div>
  );
}
